package com.lolzcloud.mobile;

import java.util.*;

/** Real DSP calculations; the independent Android suite proves these samples reach AudioTrack. */
public final class PcmDspPolicyTest {
    private static final List<String> checks=new ArrayList<>();private static final int RATE=48000;
    private static PcmDsp.Config config(long revision,boolean enabled,double[] gains,double preamp,double echo,double reverb,boolean normal){return new PcmDsp.Config(revision,enabled,gains,preamp,echo,reverb,normal);}
    private static void check(boolean value,String name){if(!value)throw new AssertionError(name);checks.add(name);}
    private static double[] render(PcmDsp dsp,double frequency,double amplitude,double seconds){float[] in=new float[2048],out=new float[2048];long frames=Math.round(seconds*dsp.sampleRate),at=0;double energy=0,raw=0,peak=0;long samples=0;while(at<frames){int count=(int)Math.min(1024,frames-at);for(int i=0;i<count;i++)for(int c=0;c<dsp.channels;c++)in[i*dsp.channels+c]=(float)(amplitude*Math.sin(2*Math.PI*frequency*(at+i)/dsp.sampleRate));dsp.process(in,out,count);for(int i=0;i<count*dsp.channels;i++){if(!Float.isFinite(out[i]))throw new AssertionError("Non-finite output");if(at>=dsp.sampleRate/4){energy+=out[i]*out[i];raw+=in[i]*in[i];samples++;}peak=Math.max(peak,Math.abs(out[i]));}at+=count;}return new double[]{Math.sqrt(energy/Math.max(1,samples)),Math.sqrt(raw/Math.max(1,samples)),peak};}
    private static PcmDsp dsp(double[] gains,double preamp,double echo,double reverb,boolean normal){return new PcmDsp(RATE,2,config(1,true,gains,preamp,echo,reverb,normal));}
    public static void main(String[] args){double[] neutral={0,0,0,0,0};
        for(int which=0;which<7;which++){boolean denied=false;try{switch(which){case 0:config(0,true,neutral,0,0,0,false);break;case 1:config(1,true,new double[4],0,0,0,false);break;case 2:config(1,true,new double[]{Double.NaN,0,0,0,0},0,0,0,false);break;case 3:config(1,true,neutral,.1,0,0,false);break;case 4:config(1,true,neutral,0,.81,0,false);break;case 5:config(1,true,neutral,0,0,Double.POSITIVE_INFINITY,false);break;default:new PcmDsp(RATE,6,config(1,true,neutral,0,0,0,false));}}catch(IllegalArgumentException expected){denied=true;}check(denied,"Reject invalid PCM configuration "+which);}
        double[] attenuated=render(dsp(neutral,-6,0,0,false),997,.1,2);check(Math.abs(20*Math.log10(attenuated[0]/attenuated[1])+6)<.03,"Preamp applies real -6dB to streaming PCM");
        double[] gains={0,0,12,0,0};double middle=render(dsp(gains,0,0,0,false),910,.05,2)[0],upper=render(dsp(gains,0,0,0,false),6000,.05,2)[0];check(middle/upper>3,"Five-band peaking EQ separates 910Hz from6000Hz after headroom");
        PcmDsp bypass=new PcmDsp(RATE,2,config(1,false,gains,-6,.8,.8,false));float[] input={.1f,-.2f,.6f,-.7f},output=new float[4];bypass.process(input,output,2);check(Arrays.equals(input,output),"Disabled common chain is exact PCM bypass");
        PcmDsp echo=dsp(neutral,0,.8,0,false);float[] impulse=new float[RATE*2],echoed=new float[impulse.length];impulse[0]=.3f;echo.process(impulse,echoed,RATE);int delayed=(int)Math.round(RATE*.28)*2;check(Math.abs(echoed[delayed]-.144)<.00001,"Echo first reflection occurs at exactly280ms");check(Math.abs(echoed[delayed*2]-.06336)<.00001,"Echo feedback follows the bounded portable strength");double before=0;for(int i=2;i<delayed;i++)before+=echoed[i]*echoed[i];check(before<1e-12,"Echo has no premature reflection");double right=0;for(int i=1;i<echoed.length;i+=2)right+=echoed[i]*echoed[i];check(right<1e-12,"Delay channels do not leak into the opposite stereo channel");
        echo.configure(config(2,true,neutral,0,.8,0,false));Arrays.fill(impulse,0);echo.process(impulse,echoed,RATE);double cleared=0;for(float value:echoed)cleared+=value*value;check(cleared<1e-12,"Discontinuity clears all old echo history");
        PcmDsp reverb=dsp(neutral,0,0,.8,false);impulse[0]=.3f;reverb.process(impulse,echoed,RATE);double tail=0;for(int i=RATE/10;i<echoed.length;i++)tail+=echoed[i]*echoed[i];check(tail>1e-7,"Algorithmic Reverb produces an actual decaying PCM tail");
        float[] loud={4,2,4,2,Float.NaN,Float.POSITIVE_INFINITY},limited=new float[loud.length];dsp(neutral,0,0,0,false).process(loud,limited,3);check(Math.abs(limited[0])<=Math.pow(10,-3d/20)+1e-6,"Stereo limiter enforces the -3dB ceiling");check(Math.abs(limited[0]/limited[1]-2)<.00001,"Linked limiting preserves stereo balance");check(Float.isFinite(limited[4])&&Float.isFinite(limited[5]),"Non-finite decoded input cannot poison DSP output");
        PcmDsp normal=new PcmDsp(RATE,2,config(1,false,gains,-6,.8,.8,true));double[] normalOutput=render(normal,997,.01,9);check(normal.measured()&&Double.isFinite(normal.loudness()),"K-weighted400ms blocks become measured after the warmup");check(normal.targetDb()==8&&normal.normalizationDb()>5&&normal.normalizationDb()<6.1,"Quiet material targets bounded +8dB and slews at1dB per source second");check(normalOutput[0]>normalOutput[1]*1.2,"Independent normalization changes output while the common EQ/effect master is off");
        PcmDsp silence=dsp(neutral,0,0,0,true);render(silence,997,0,5);check(!silence.measured()&&silence.normalizationDb()==0,"Absolute gate does not amplify digital silence");render(normal,997,0,1);double measured=normal.loudness();render(normal,997,0,2);check(Math.abs(normal.loudness()-measured)<.001,"Fully silent blocks below the absolute gate do not change integrated loudness");
        double beforeGain=normal.normalizationDb();normal.configure(config(2,true,neutral,-6,0,0,true));check(normal.measured()&&normal.normalizationDb()==beforeGain,"An EQ/preamp revision preserves independent normalizer learning");normal.reset(config(3,true,neutral,-6,0,0,true));check(!normal.measured()&&normal.normalizationDb()==0,"Seek/source discontinuity resets the loudness measurement history");
        PcmDsp.Meter meter=new PcmDsp.Meter();meter.reset(12,RATE,2);meter.accepted(new float[]{1,2,3,4},new float[]{.5f,1,1.5f,2},0,2);check(meter.acceptedFrames==1&&meter.inputEnergy==5&&meter.outputEnergy==1.25,"Accepted-sample meter counts only a successful partial stereo write");meter.reset(13,RATE,2);check(meter.acceptedFrames==0&&meter.outputEnergy==0&&meter.revision==13,"New revision cannot inherit old render metrics");
        for(int rate:new int[]{8000,44100,48000,96000,192000}){PcmDsp bounded=new PcmDsp(rate,1,config(1,true,new double[]{12,-12,12,-12,12},-12,.8,.8,true));double peak=render(bounded,Math.min(1000,rate/8),.8,.5)[2];check(peak<=Math.pow(10,-3d/20)+1e-6,"Bounded finite mono DSP at "+rate+"Hz");}
        StringBuilder json=new StringBuilder("{\"status\":\"passed\",\"checks\":[");for(int i=0;i<checks.size();i++){if(i>0)json.append(',');json.append('"').append(checks.get(i)).append('"');}json.append("],\"scope\":\"Actual streaming Java DSP maths, not an AudioTrack or physical audio proof. Native render-path instrumentation is separate.\"}");System.out.print(json);
    }
}
